// A local stand-in for the `stripe` package, present so the generated handler
// can be EXECUTED in tests without a network or an install.
//
// Only one method matters here and it is not simulated: constructEvent does
// the real HMAC-SHA256 verification Stripe documents, against the raw body,
// with the signing secret used verbatim as the key. If Akeso's generated
// handler mis-handles the raw body or the signature, this rejects it exactly
// like the real SDK would.
import { createHmac, timingSafeEqual } from "node:crypto";

class StripeSignatureVerificationError extends Error {}

export default class Stripe {
  constructor(apiKey) {
    this.apiKey = apiKey;
    this.webhooks = {
      constructEvent: (rawBody, signatureHeader, secret) => {
        if (!signatureHeader) throw new StripeSignatureVerificationError("no stripe-signature header");
        const body = typeof rawBody === "string" ? rawBody : Buffer.from(rawBody).toString("utf8");
        const parts = Object.fromEntries(String(signatureHeader).split(",").map((part) => part.split("=")));
        if (!parts.t || !parts.v1) throw new StripeSignatureVerificationError("malformed signature header");

        const expected = createHmac("sha256", secret).update(`${parts.t}.${body}`).digest("hex");
        let ok = false;
        try { ok = timingSafeEqual(Buffer.from(expected, "hex"), Buffer.from(parts.v1, "hex")); } catch { ok = false; }
        if (!ok) throw new StripeSignatureVerificationError("no signatures found matching the expected signature for payload");

        return JSON.parse(body);
      },
    };
  }
}
